package pe.farmagest.inventario.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import org.springframework.data.domain.PageRequest;
import pe.farmagest.inventario.entity.*;import pe.farmagest.inventario.repository.*;import pe.farmagest.inventario.dto.ConteoDto;import pe.farmagest.inventario.security.JwtAuthenticationFilter.UserPrincipal;
import java.time.*;import java.util.*;
@Service @Transactional(isolation=Isolation.READ_COMMITTED)
public class ConteoService {
 private final ConteoRepository sesiones;private final ConteoLineaRepository lineas;private final ConteoEventoRepository eventos;private final ConteoFotoRepository fotos;private final ProductoStockRepository stocks;private final MovimientoKardexRepository kardex;private final ConteoCatalogoClient catalogo;
 public ConteoService(ConteoRepository s,ConteoLineaRepository l,ConteoEventoRepository e,ConteoFotoRepository f,ProductoStockRepository p,MovimientoKardexRepository k,ConteoCatalogoClient c){sesiones=s;lineas=l;eventos=e;fotos=f;stocks=p;kardex=k;catalogo=c;}
 private static LocalDateTime ahora(){return LocalDateTime.now(ZoneOffset.UTC);}
 private static Instant instante(LocalDateTime f){return f==null?null:f.toInstant(ZoneOffset.UTC);}
 private static ResponseStatusException error(HttpStatus status,String msg){return new ResponseStatusException(status,msg);}
 public void acceso(Integer sucursal,UserPrincipal user){if(sucursal==null||sucursal<1)throw error(HttpStatus.BAD_REQUEST,"Sucursal inválida");if(!user.getRoles().contains("ROLE_ADMINISTRADOR")&&user.getSucursalId().longValue()!=sucursal.longValue())throw error(HttpStatus.FORBIDDEN,"No puedes acceder a otra sucursal");}
 private ConteoFisico obtener(Long id,UserPrincipal user,boolean editar){ConteoFisico c=sesiones.bloquear(id).orElseThrow(()->error(HttpStatus.NOT_FOUND,"Conteo no encontrado"));acceso(c.sucursalId,user);if(editar && !user.getRoles().contains("ROLE_ADMINISTRADOR")&&!c.usuarioId.equals(user.getUserId()))throw error(HttpStatus.FORBIDDEN,"Solo el responsable o un administrador puede editar este conteo");return c;}
 private void abierto(ConteoFisico c){if(!"ABIERTO".equals(c.estado))throw error(HttpStatus.CONFLICT,"El conteo ya está cerrado y no se puede editar");}
 private void evento(ConteoFisico c,UserPrincipal user,String accion,String detalle){var e=new ConteoEvento();e.conteoId=c.id;e.usuarioId=user.getUserId();e.fecha=ahora();e.accion=accion;e.detalle=detalle;eventos.save(e);}
 public List<ConteoDto> listar(Integer sucursal,int pagina,UserPrincipal user){acceso(sucursal,user);if(pagina<0)throw error(HttpStatus.BAD_REQUEST,"Página inválida");return sesiones.findBySucursalIdOrderByIdDesc(sucursal,PageRequest.of(pagina,20)).stream().map(c->dto(c,false)).toList();}
 public ConteoDto ver(Long id,UserPrincipal user){return dto(obtener(id,user,false),true);}
 public ConteoDto crear(Integer sucursal,String referencia,UserPrincipal user){acceso(sucursal,user);if(referencia==null||referencia.isBlank()||referencia.trim().length()>100)throw error(HttpStatus.BAD_REQUEST,"Indica una referencia de hasta 100 caracteres");
  var actuales=stocks.bloquearSucursal(sucursal);var c=new ConteoFisico();c.sucursalId=sucursal;c.referencia=referencia.trim();c.usuarioId=user.getUserId();c.creadoEn=ahora();c.estado="ABIERTO";c.marcador=kardex.ultimoIdSucursal(sucursal);sesiones.saveAndFlush(c);
  for(var stock:actuales){var l=new ConteoLinea();l.conteoId=c.id;l.productoId=stock.getProductoId();l.stockInicial=stock.getStockActual();l.actualizadoInicial=stock.getActualizadoEn();lineas.save(l);}
  evento(c,user,"CREAR","Conteo ciego iniciado; alcance: productos contados en toda la sucursal.");return dto(c,true);
 }
 public ConteoDto contar(Long id,Long productoId,Integer cantidad,String observacion,UserPrincipal user,String auth){var c=obtener(id,user,true);abierto(c);if(productoId==null||productoId<1||cantidad==null||cantidad<0||cantidad>100000000||observacion!=null&&observacion.length()>500)throw error(HttpStatus.BAD_REQUEST,"Cantidad entera entre 0 y 100000000 y observación de hasta 500 caracteres");
  var p=catalogo.obtener(productoId,auth);var l=lineas.findByConteoIdAndProductoId(id,productoId).orElseGet(()->{var nueva=new ConteoLinea();nueva.conteoId=id;nueva.productoId=productoId;nueva.stockInicial=0;return nueva;});
  String previo=l.cantidad==null?"sin contar":l.cantidad.toString();l.nombre=p.nombre();l.codigo=p.codigo();l.presentacion=p.presentacion();l.cantidad=cantidad;l.observacion=observacion==null?"":observacion.trim();l.usuarioId=user.getUserId();l.contadoEn=ahora();lineas.saveAndFlush(l);
  evento(c,user,"CONTAR","Producto #"+productoId+": "+previo+" → "+cantidad+" unidades base. "+l.observacion);return dto(c,true);
 }
 public static String resultado(ConteoLinea linea,ProductoStock actual,long ultimoMovimiento,long marcador){
  boolean cambio=ultimoMovimiento>marcador || (actual==null?0:actual.getStockActual())!=linea.stockInicial || !Objects.equals(actual==null?null:actual.getActualizadoEn(),linea.actualizadoInicial);
  if(cambio)return "REQUIERE_RECONTEO";long diferencia=(long)linea.cantidad-linea.stockInicial;return diferencia==0?"CONFORME":diferencia<0?"FALTANTE":"SOBRANTE";
 }
 public ConteoDto cerrar(Long id,UserPrincipal user){var c=obtener(id,user,true);abierto(c);var contadas=lineas.findByConteoIdOrderByIdAsc(id).stream().filter(l->l.cantidad!=null).toList();if(contadas.isEmpty())throw error(HttpStatus.CONFLICT,"Registra al menos un producto antes de finalizar");
  var actuales=new HashMap<Long,ProductoStock>();for(var stock:stocks.bloquearSucursal(c.sucursalId))actuales.put(stock.getProductoId(),stock);
  for(var l:contadas){l.resultado=resultado(l,actuales.get(l.productoId),kardex.ultimoIdProducto(c.sucursalId,l.productoId),c.marcador);lineas.save(l);}
  c.estado="FINALIZADO";c.cerradoEn=ahora();sesiones.save(c);evento(c,user,"FINALIZAR","Comparación finalizada sin modificar stock. Los productos no contados quedan fuera del resultado.");return dto(c,true);
 }
 public ConteoDto cancelar(Long id,UserPrincipal user){var c=obtener(id,user,true);abierto(c);c.estado="CANCELADO";c.cerradoEn=ahora();sesiones.save(c);evento(c,user,"CANCELAR","Sesión cancelada; evidencia conservada.");return dto(c,true);}
 public ConteoDto revisar(Long id,String nota,UserPrincipal user){var c=obtener(id,user,true);if(!user.getRoles().contains("ROLE_ADMINISTRADOR"))throw error(HttpStatus.FORBIDDEN,"Solo el administrador puede registrar la revisión");if(!"FINALIZADO".equals(c.estado)||nota==null||nota.isBlank()||nota.length()>1000)throw error(HttpStatus.BAD_REQUEST,"Finaliza el conteo e indica la revisión (máximo 1000 caracteres)");if(c.revisadoEn!=null)throw error(HttpStatus.CONFLICT,"La revisión ya está registrada");c.revision=nota.trim();c.revisadoPor=user.getUserId();c.revisadoEn=ahora();sesiones.save(c);evento(c,user,"REVISAR",c.revision);return dto(c,true);}
 public ConteoDto foto(Long id,byte[] bytes,String tipo,UserPrincipal user){var c=obtener(id,user,true);abierto(c);if(c.tieneFoto)throw error(HttpStatus.CONFLICT,"Esta sesión ya tiene una foto. Se conserva la evidencia original.");validarFoto(bytes,tipo);var f=new ConteoFoto();f.id=id;f.contenido=bytes;f.tipo=tipo;fotos.save(f);c.tieneFoto=true;sesiones.save(c);evento(c,user,"FOTO","Foto de evidencia adjuntada. No se usa para contar productos automáticamente.");return dto(c,true);}
 public static void validarFoto(byte[] b,String t){boolean jpg="image/jpeg".equals(t)&&b.length>3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;boolean png="image/png".equals(t)&&b.length>8&&b[0]==(byte)137&&b[1]==80&&b[2]==78&&b[3]==71;boolean webp="image/webp".equals(t)&&b.length>12&&new String(b,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(b,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP");if(b.length==0||b.length>8*1024*1024||!jpg&&!png&&!webp)throw error(HttpStatus.BAD_REQUEST,"Adjunta una imagen JPG, PNG o WebP válida de hasta 8 MB");try{var imagen=javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(b));if(!webp&&(imagen==null||(long)imagen.getWidth()*imagen.getHeight()>40000000))throw error(HttpStatus.BAD_REQUEST,"Imagen no válida o demasiado grande");}catch(java.io.IOException e){throw error(HttpStatus.BAD_REQUEST,"Imagen no válida");}}
 public ConteoFoto obtenerFoto(Long id,UserPrincipal user){obtener(id,user,false);return fotos.findById(id).orElseThrow(()->error(HttpStatus.NOT_FOUND,"Sin foto adjunta"));}
 private ConteoDto dto(ConteoFisico c,boolean detalle){boolean visible="FINALIZADO".equals(c.estado);var rows=detalle?lineas.findByConteoIdOrderByIdAsc(c.id).stream().filter(l->l.cantidad!=null).map(l->{boolean comparable=visible&&!"REQUIERE_RECONTEO".equals(l.resultado);return new ConteoDto.Linea(l.productoId,l.nombre,l.codigo,l.presentacion,l.cantidad,l.usuarioId,instante(l.contadoEn),l.observacion,comparable?l.stockInicial:null,comparable?(long)l.cantidad-l.stockInicial:null,visible?l.resultado:null);}).toList():List.<ConteoDto.Linea>of();
  var history=detalle?eventos.findByConteoIdOrderByIdAsc(c.id).stream().map(e->new ConteoDto.Evento(e.usuarioId,instante(e.fecha),e.accion,e.detalle)).toList():List.<ConteoDto.Evento>of();
  return new ConteoDto(c.id,c.sucursalId,c.referencia,c.usuarioId,instante(c.creadoEn),instante(c.cerradoEn),c.estado,c.tieneFoto,c.revision,c.revisadoPor,instante(c.revisadoEn),rows,history);
 }
}
